/**
 * Capsule vs Points collision detection using PointsBVH shapecast.
 *
 * Tests a dynamic body's capsule against a static point cloud.
 * Each point in the cloud is treated as a sphere with the body's pointsRadius.
 * Accumulates ALL collision responses directly into deltaPosition.
 *
 * @param {THREE.Line3} segment - Capsule segment in world space
 * @param {number} capsuleRadius - Capsule collision radius
 * @param {THREE.Box3} capsuleBox - Capsule AABB for broad phase
 * @param {Object} pointsBody - Static body with PointsBVH and pointsRadius
 * @param {THREE.Vector3} deltaPosition - Accumulated collision response output
 * @param {Object} collisionInfo - Output object for tracking deepest collision { normal, groundNormal, surfaceAngle, groundAngle }
 * @param {THREE.Vector3} gravityUp - Gravity up vector for surface angle calculation
 * @returns {boolean} True if collision detected
 */
export function capsulePointsCollide(segment: THREE.Line3, capsuleRadius: number, capsuleBox: THREE.Box3, pointsBody: any, deltaPosition: THREE.Vector3, collisionInfo: any, gravityUp: THREE.Vector3): boolean;
/**
 * Batch collision test for capsule against multiple point cloud bodies.
 *
 * Efficient when testing against multiple point cloud colliders.
 * Accumulates all collision responses into deltaPosition.
 *
 * @param {THREE.Line3} segment - Capsule segment in world space
 * @param {number} capsuleRadius - Capsule collision radius
 * @param {THREE.Box3} capsuleBox - Capsule AABB for broad phase
 * @param {Array<Object>} pointsBodies - Array of point cloud bodies to test
 * @param {THREE.Vector3} deltaPosition - Accumulated collision response
 * @param {Object} api - Dynamic body API for tracking collision state
 * @param {THREE.Vector3} gravityUp - Gravity up vector for surface angle calculation
 * @returns {boolean} True if any collision detected
 */
export function capsulePointsCollideBatch(segment: THREE.Line3, capsuleRadius: number, capsuleBox: THREE.Box3, pointsBodies: Array<any>, deltaPosition: THREE.Vector3, api: any, gravityUp: THREE.Vector3): boolean;
